// src/api/NotificationsApi.js
import { get } from './HttpClient';

function buildQuery(params = {}) {
  const qs = new URLSearchParams();
  Object.entries(params).forEach(([k, v]) => {
    if (v === undefined || v === null) return;
    const s = String(v).trim();
    if (!s) return;
    qs.set(k, s);
  });
  const q = qs.toString();
  return q ? `?${q}` : '';
}

// GET /alerts?page=&size=&from=&to=&level=&keyword=
export function fetchAlerts(params) {
  return get(`/alerts${buildQuery(params)}`);
}

// GET /alerts/{id}
export function fetchAlertDetail(id) {
  return get(`/alerts/${id}`);
}

// GET /alerts/stats?range=daily|weekly&from=&to=
export function fetchAlertStats(params) {
  return get(`/alerts/stats${buildQuery(params)}`);
}
